            .ai-chat-message {
                display: flex;
                flex-direction: column;
                gap: 8px;
                animation: slideIn 0.3s ease-out;
            }
            @keyframes slideIn {
                from {
                    opacity: 0;
                    transform: translateY(10px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }
            .ai-chat-message.user {
