                    if (convertExportBtn) convertExportBtn.style.background = 'linear-gradient(135deg, #10b981, #059669)';
                    if (convertTabPdfa) { convertTabPdfa.style.borderBottomColor = '#10b981'; convertTabPdfa.style.color = '#e5e7eb'; }
                } else if (tab === 'word') {
